import base64
import json

import cmcc_crypto

_BLOB_B64 = ""

_BUILTIN = json.loads(base64.b64decode(_BLOB_B64))
XK = _BUILTIN.get('xk')
URLS = _BUILTIN['urls']
HEADERS = _BUILTIN.get('headers', {})
COOKIES = _BUILTIN.get('cookies', {})
BODIES = _BUILTIN.get('bodies', {})


def _clone(name):
    return json.loads(json.dumps(BODIES[name]))


def build_send_code(phone):
    body = _clone('send_code')
    body['reqBody']['cellNum'] = phone
    url = URLS['send_code']
    headers, payload, body_json = cmcc_crypto.build_signed(url, body, XK)
    return url, headers, payload, body_json


def build_login(phone, code, put_code='t'):
    body = _clone('login')
    cell, _ = cmcc_crypto.cell_num(phone)
    body['reqBody']['cellNum'] = cell
    if put_code == 't':
        body['t'] = code
    elif put_code == 'reqBody.t':
        body['reqBody']['t'] = code
    elif put_code == 'reqBody.verifyCode':
        body['reqBody']['verifyCode'] = code
    else:
        body['reqBody']['randCode'] = code
    url = URLS['login']
    headers, payload, body_json = cmcc_crypto.build_signed(url, body, XK)
    return url, headers, payload, body_json


def build_three_net(phone, code, dev_token=None):
    body = _clone('three_net')
    cell, _ = cmcc_crypto.cell_num(phone)
    body['reqBody']['cellNum'] = cell
    body['reqBody']['verifyCode'] = code
    if dev_token:
        body['reqBody']['devToken'] = dev_token
    else:
        body['reqBody'].pop('devToken', None)
    body['tel'] = phone
    url = URLS['three_net']
    headers, payload, body_json = cmcc_crypto.build_signed(url, body, XK)
    return url, headers, payload, body_json


def h5_token_payload(session_token, jwt_token=None, phone=None):
    body = _clone('h5_token')
    if session_token:
        body['token'] = session_token
    if jwt_token:
        body['jwtToken'] = jwt_token
    elif 'jwtToken' in body:
        body['jwtToken'] = None
    if phone:
        try:
            body['userCheckId'] = '%x' % int(phone)
        except Exception:
            pass
    return body


def user_info_payload():
    return _clone('user_info')


def user_info_meta():
    return URLS.get('user_info'), HEADERS.get('user_info', {}), COOKIES.get('user_info', {})


def h5_token_meta():
    return URLS.get('h5_token'), HEADERS.get('h5_token', {}), COOKIES.get('h5_token', {})


def sso_page_meta():
    return URLS.get('sso_page'), HEADERS.get('sso_page', {}), COOKIES.get('sso_page', {})


def summary():
    return {
        'xk_set': bool(XK),
        'endpoints': {k: v for k, v in URLS.items()},
        'note': ('内置报文模板：启动无需任何抓包文件；'
                 '加密通道 x-token / x-sign 由内置 xk 推导，请求体由内置 KEY_14 加密。'),
    }
